const a={l:[1,2,3],o:{x:[{a:1},{b:2}]},n:null,e:''};const p={l:[9],o:{x:[{c:3}]},n:{q:1},e:5};
console.log(JSON.stringify(merge(structuredClone(a),p)),JSON.stringify(c.merge(structuredClone(a),p)));
EOF
